insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('16ff4a51-d956-4ee9-bd1d-b820aaad519a', 'de', 'Was heißt es, tagsüber beim Ansprechen fein abgestimmt zu sein?', '["Deine Energie an ihre anpassen", "Dich danach richten, wie wohl sie sich fühlt", "Respektvoll bleiben", "Alle oben genannten"]'::jsonb, 'Feingefühl ist gelebte Aufmerksamkeit: Du liest ihre Reaktion und passt dich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17e5ea51-94a8-4084-bfd8-18b8a92f9ae9', 'de', 'Was lehnen Frauen beim Ansprechen tagsüber ab?', '["Dass Fremde sie in der Öffentlichkeit ansprechen", "Dass Männer sie bei Besorgungen und im Alltag unterbrechen", "Dass jemand tagsüber offen romantisches Interesse zeigt", "Eine Ansprache, die Wohlgefühl und Respekt missachtet"]'::jsonb, 'Unbehagen entsteht, wenn Grenzen missachtet werden, nicht durch das Ansprechen an sich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c7c4962-c5cf-480e-94ba-1cc03443f821', 'de', 'In einem Laden siehst du eine Frau, die in Büchern stöbert. Welche Ansprache gibt ihr ein gutes Gefühl?', '["Von hinten herangehen und ihr auf die Schulter tippen", "Sofort ihr Aussehen loben", "Warten, bis sie dich zuerst ansieht", "In ihr Blickfeld treten, ruhig lächeln und dann Hallo sagen"]'::jsonb, 'Wenn sie dich kommen sieht und du lächelst, zeigt das Respekt und vermeidet einen Schreckmoment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f1937b7-4e35-4007-97d7-0ba51bfa30af', 'de', 'Warum wird Zögern abends besonders bestraft?', '["Frauen werden ständig angesprochen und haben mehr Auswahl", "In trubeligen Locations wechselt die Aufmerksamkeit schnell, und Gelegenheiten sind schnell weg", "Alkohol macht Leute ungeduldiger und weniger nachsichtig", "Andere Männer sprechen sie an, wenn du nicht schnell bist"]'::jsonb, 'Abends ändert sich die Situation schnell. Wer zögert, macht aus Signalen verpasste Chancen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c6d0086-b465-4912-9e47-4cec5bc122f2', 'de', 'In einer lauten Location steigst du ruhig ein, sprichst aber leise. Was passiert wahrscheinlich?', '["Sie lehnt sich zu dir", "Das Gespräch wirkt geerdet", "Der Schwung geht verloren", "Die Anziehung steigt"]'::jsonb, 'Wenig Energie, die nicht zur Umgebung passt, lässt das Interesse abflauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e4f60ca8-4125-463e-b6ce-3c84259813a8', 'de', 'Sie bestellt an der Bar. Du stellst dich zum Bestellen neben sie. Sie wirft dir einen Blick zu. Dein Zug?', '["Erst deinen Drink bestellen und sie ansprechen, wenn ihr beide etwas habt", "Abwarten, ob sie noch ein Signal gibt", "Hallo sagen und mit ihr ins Gespräch kommen"]'::jsonb, 'Warte nicht auf weitere Signale. Abends reicht ein Blick, um anzufangen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbc9b59e-d2c5-4cb0-be94-f4bc54ea2bca', 'de', 'Was ist das Ziel, wenn du eine Gruppe ansprichst?', '["Die Frau, die dich interessiert, beeindrucken, um dich von anderen abzuheben", "Von allen akzeptiert werden und dich dann ihr zuwenden", "Den Wortführer der Gruppe ausmachen und dich mit ihm anfreunden", "So viel bieten, dass die Gruppe dich einlädt, dazuzukommen"]'::jsonb, 'Wenn du die ganze Gruppe beachtest, bekommst du ihr Okay. Bezieh alle ein, bevor du dich auf eine Person konzentrierst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10add83c-809f-43e0-aa9a-31d38bfb3270', 'de', 'Eine Gruppe lacht laut. Du kommst mit einer leisen, ernsten Bemerkung dazu. Was passiert?', '["Die unpassende Energie lässt das Interesse abflauen", "Sie lassen sich voll auf dich ein", "Sie schätzen deine Echtheit", "Die Frau, die dich interessiert, zieht dich zur Seite"]'::jsonb, 'Unpassende Energie lässt das Interesse abflauen. Spiegel ihre Begeisterung, damit der Fluss erhalten bleibt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2efcf135-1220-4266-bbc1-7828bea5592d', 'de', 'Welche Veränderung in der Einstellung hilft Männern, Gruppen erfolgreich anzusprechen?', '["Ihre Freundinnen als mögliche Verbündete sehen, nicht als Hindernis", "Davon ausgehen, dass Gruppen immer schwieriger sind als Frauen allein", "Dich erst mal nur darauf konzentrieren, sie zu beeindrucken"]'::jsonb, 'Wenn sich die Gruppe gesehen fühlt, fällt die Verbindung zu einer Einzelnen leichter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4756728e-4c07-484b-a976-9eeb5814eca7', 'de', 'Du steigst ein mit: „Ich hab eine Frage an dich.“ Sie schaut erwartungsvoll auf. Was zeigt das?', '["Höflichkeit", "Neugier", "Prüfung", "Ablehnung"]'::jsonb, 'Neugier wirkt, weil sie ganz natürlich Aufmerksamkeit anzieht. Steig mit etwas ein, das neugierig macht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28aa155d-35ca-4afd-abcc-bc4cb3e22a6d', 'de', 'Warum funktioniert „Ich brauch mal die Meinung einer Frau“ als Einstieg so gut?', '["Sie fühlt sich geschätzt und wichtig für das Gespräch", "Es macht neugierig, worum es bei der Frage geht", "Beides"]'::jsonb, 'Das funktioniert, weil sie dadurch wichtig ist. Sie fühlt sich von Anfang an einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7aa7c045-3cd0-4ffe-aa02-400edd9bc5b7', 'de', 'Warum ziehen Neugier-Opener besser als direkte Fragen?', '["Sie wecken den Drang des Gehirns, Wissenslücken zu schließen", "Sie liefern sofort sachliche Antworten", "Sie wecken in ihr den Wunsch zu erfahren, wie es weitergeht"]'::jsonb, 'Neugier erzeugt einen psychologischen Sog, der stärker ist als das übliche Desinteresse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f40037b2-a636-4084-a804-c553ece3de6a', 'de', 'Welchen Vorteil haben Opener mit einer Vermutung am Anfang?', '["Sie zeigen Dominanz", "Sie beziehen sie sofort ein", "Sie verbergen deine Absicht", "Sie senken das Risiko"]'::jsonb, 'Eine Vermutung verlangt nach einer Antwort und bezieht sie sofort ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3e974466-6524-42dc-a429-63bb8e831188', 'de', 'Warum beziehen Opener wie „Du machst Pilates, oder?“ sie sofort ein?', '["Sie zeigen, dass du ihre Fitness genau wahrnimmst", "Sie beziehen sie sofort ein: Sie muss korrigieren oder bestätigen", "Sie zeigen, dass du dich mit Fitness und Gesundheit auskennst"]'::jsonb, 'Eine Vermutung verlangt nach einer Antwort. Sie ist sofort dabei, zu korrigieren oder zu bestätigen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1874cbce-d4aa-44b1-ab88-ff0c2745d69f', 'de', 'Warum fesseln Opener mit einer Vermutung besser als allgemeine Fragen?', '["Sie machen neugierig, wie du sie wahrnimmst", "Man kann sie auf Autopilot beantworten", "Sie verlangen eine Bestätigung oder Korrektur"]'::jsonb, 'Eine Vermutung gibt ihr das Gefühl, gesehen zu werden, und bezieht sie sofort ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e84223a-e094-4ee6-8da9-79cd89d634c7', 'de', '„Ich brauch mal die Meinung einer Frau“ funktioniert, weil:', '["es neugierig macht, wozu du eine Meinung brauchst", "sie das Gefühl bekommt, dass ihre Sicht geschätzt wird und wichtig ist", "es Frauen als Expertinnen mit einem Blick darstellt, den du brauchst", "Alle oben genannten"]'::jsonb, 'Es macht neugierig, gibt ihr das Gefühl, geschätzt zu werden, und macht die weibliche Sicht wertvoll.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc959e07-994f-4a1d-b948-b437f3e6f2b2', 'de', 'Du steigst mit einem Dilemma ein. Sie antwortet ausführlich. Was könntest du als Nächstes tun?', '["Das Gespräch beenden", "Ihr voll zustimmen", "Das Thema wechseln", "Auf ihrer Antwort aufbauen"]'::jsonb, 'Wenn du auf ihrer Antwort aufbaust, würdigst du ihre Mühe und hältst den Schwung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c800f82-c80b-490c-988f-e66f6100d311', 'de', 'Welche Opener zeigen, dass dir ihre Sicht wichtig ist?', '["„Ich brauch mal die Meinung einer Frau“", "„Kurze Frage an dich“", "„Du bist sehr attraktiv“", "„Mein Kumpel und ich haben gerade diskutiert“"]'::jsonb, 'Diese Opener machen sie wichtig. Sie fühlt sich von Anfang an einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43b03548-630d-4716-8d45-71c89fa4a819', 'de', 'Was ist beim Ansprechen ein Zeitlimit?', '["Eine Frist, die du ihr für eine Antwort setzt", "Eine Technik, um im Gespräch Dringlichkeit und Knappheit zu erzeugen", "Ein Satz am Anfang, der zeigt, dass du gleich wieder gehst"]'::jsonb, 'Wenn du sagst, dass du nicht lange bleibst, nimmt das Druck raus. Setz es gleich am Anfang ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfb43838-50ce-4ae4-8c8a-722afd35d73a', 'de', 'Was ist das Ziel eines Zeitlimits am Anfang?', '["Das Gespräch kontrollieren, indem du dich als beschäftigt darstellst", "Knappheit erzeugen, damit sie deine Zeit mehr schätzt", "Ihr ein gutes Gefühl geben, weil sie sich auf nichts Unabsehbares einlassen muss"]'::jsonb, 'Wenn du sagst, dass du nicht lange bleibst, nimmt das Druck raus. Setz es gleich am Anfang ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66801814-05f0-417d-a387-606cb86e6cf9', 'de', 'Du sprichst eine Frau im Café an. Was kannst du zuerst sagen, um Druck rauszunehmen?', '["Sofort ihr Aussehen loben", "Sagen, dass du nur kurz Zeit hast", "Tiefe persönliche Fragen stellen", "Vorschlagen, woandershin zu gehen"]'::jsonb, 'Ein Zeitlimit zeigt, dass du gleich wieder gehst, und sie wird weniger vorsichtig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8993be7c-90eb-4430-96e6-83d657f55add', 'de', 'Woran merkst du, dass es Zeit für einen vorgetäuschten Abgang ist?', '["Die Stimmung ist auf dem Höhepunkt, sie lacht und ist voll dabei", "Das Gespräch hat gerade erst begonnen, ihr baut noch eine Verbindung auf", "Du spürst, dass die Energie gleich stagniert oder nachlässt", "Ihr redet genau 10 Minuten, egal wie die Stimmung ist"]'::jsonb, 'Höhepunkt der Stimmung oder kurz bevor sie abflacht: Das ist das richtige Timing. Eine feste Zeitmarke spielt keine Rolle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6866bb5-1e8c-4c24-9fa6-7ea784314163', 'de', 'Was bewirkt ein vorgetäuschter Abgang?', '["Er schafft eine Lücke, weil du gehst, bevor das Gespräch von selbst endet", "Er zeigt Fülle: Du musst nicht jede Sekunde ausquetschen", "Er verhindert, dass du anfängst, um Bestätigung zu werben", "Er garantiert, dass sie später auf jeden Fall weiterreden will"]'::jsonb, 'Eine Lücke schaffen, Fülle zeigen, nicht um Bestätigung werben: Das bringt dir der vorgetäuschte Abgang.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d51f94a-3406-49fb-98ed-99beb074d2bf', 'de', '„Das war lustig, ich sollte mich mal ein bisschen unter die Leute mischen. Ich find dich später.“ Du gehst. Was hast du damit geschaffen?', '["Das Risiko, dass sie das Interesse verliert oder jemand anderen kennenlernt", "Einen positiven, offenen Eindruck und Neugier, wann du wiederkommst", "Verwirrung, ob du überhaupt Interesse an ihr hast", "Den Eindruck, dass du es mit ihr nicht ganz ernst meinst"]'::jsonb, 'Auf dem Höhepunkt gehen heißt: positive Erinnerung plus Neugier. Sie will mehr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30461b26-dac7-40f7-ae3f-bc7f90b1ebcb', 'de', 'Was ist der Unterschied zwischen nicht ansprechen und eine Abfuhr bekommen?', '["Eine Abfuhr tut im Moment mehr weh", "Nicht ansprechen schützt dein Ego und dein Selbstbewusstsein", "Eine Abfuhr bringt dir Erfahrung, nicht ansprechen bringt dir gar nichts"]'::jsonb, 'In beiden Fällen entsteht keine Verbindung, aber eine Abfuhr gibt dir Erfahrung fürs nächste Mal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46975d8e-4143-4ea5-9c92-bde52c3bebad', 'de', 'Was ist beim Ansprechen das schlimmste Ergebnis?', '["Eine höfliche Abfuhr", "Ein kurzes, gescheitertes Gespräch", "Reue, weil du nichts getan hast", "Peinliche Stille"]'::jsonb, 'Reue über verpasste Chancen hält länger an als eine kurze Abfuhr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('05af8c26-1d5f-4746-bd8d-93ffa9ceb943', 'de', 'Warum ist eine Abfuhr besser, als gar nicht anzusprechen?', '["Sie garantiert anhaltende Reue", "Sie bringt dir Erfahrung und Erkenntnisse", "Sie schafft die Möglichkeit einer Verbindung", "Sie beseitigt jede Unsicherheit"]'::jsonb, 'Handeln öffnet Türen. Nichtstun schließt sie mit Sicherheit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3400a772-93ac-48a3-a167-060ae3d525d8', 'de', 'Womit beginnt fast jede Verbindung im Leben?', '["Gemeinsame Interessen", "Das richtige Timing", "Selbstbewusstsein", "Jemand sagt als Erstes etwas"]'::jsonb, 'Jede Verbindung beginnt, weil jemand den ersten Schritt macht und etwas sagt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf5ff661-2958-4e0d-ab57-b3ef0436b379', 'de', 'Du bist auf der Party eines Freundes und kennst kaum jemanden. Was könntest du als Erstes tun?', '["Still in der Ecke bleiben, bis dich jemand anspricht", "Jemanden fragen, woher er den Gastgeber kennt", "Auf den perfekten ersten Satz warten", "Früh gehen, um peinliche Momente zu vermeiden"]'::jsonb, 'Wer zuerst spricht, schafft Chancen. Wer schweigt, hat garantiert keine.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('833fb7a5-48fa-44ca-bb33-3134723fc718', 'de', 'Wozu kann es führen, wenn du den Mund aufmachst?', '["Neue Freundschaften", "Neue Erfahrungen", "Garantierter Erfolg", "Unerwartete Gelegenheiten"]'::jsonb, 'Wer sich einbringt, öffnet sich für ganz unterschiedliche Möglichkeiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('588b3d53-613d-4e21-bdeb-77f6157427c7', 'de', 'Warum solltest du mit Neugier statt mit einer Absicht ansprechen?', '["Neugier ist leiser, eine Absicht wirkt selbstbewusster", "Neugier vermeidet Anziehung, eine Absicht erzeugt sie", "Neugier will wissen, wer sie ist, eine Absicht will ein Ergebnis"]'::jsonb, 'Neugier will den Menschen kennenlernen. Eine Absicht will ein Ergebnis herausholen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4003461a-b8aa-4eaa-b66f-3d5847986f38', 'de', 'Du siehst Island-Sticker auf ihrem Laptop. Welcher Opener zeigt echte Neugier?', '["„Hi, ich fand dich süß und wollte dich kennenlernen.“", "„Darf ich dich auf einen Kaffee einladen?“", "„Du siehst aus, als würdest du viel reisen.“", "„Ist das ein Sticker aus Island? Da war ich letztes Jahr.“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d398047f-31f2-46cb-991f-abb7e05f231d', 'de', 'Warum entsteht durch Neugier eine stärkere Verbindung als durch eine Absicht?', '["Sie behandelt sie wie ein Ziel, das du erreichen willst", "Sie gibt ihr das Gefühl, interessant zu sein und gesehen zu werden", "Sie nimmt den Druck raus, ein Ergebnis herauszuholen", "Sie ermöglicht ein müheloseres, echteres Gespräch"]'::jsonb, 'Neugier richtet sich auf sie als Mensch und fördert eine natürliche Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7265d45c-cbbc-4d5e-8220-2d1c5fe793f2', 'de', 'Warum fühlt sich Ansprechen schwerer an, wenn du es selten tust?', '["Es fühlt sich an, als stünde mehr auf dem Spiel", "Die Erfolgschancen sinken", "Das Timing wird schlechter", "Die Angst wächst"]'::jsonb, 'Wenn du selten ansprichst, hat jedes Mal mehr Gewicht und fühlt sich intensiver an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31e5395b-0177-4703-8182-44c9921a16fc', 'de', 'Welcher Fehler führt dazu, dass man seltener anspricht, als man könnte?', '["An den falschen Orten sein", "Auf ideale Bedingungen warten", "Am Handy hängen", "Mangelndes Interesse"]'::jsonb, 'Wer auf perfekte Bedingungen wartet, hat insgesamt weniger Gelegenheiten. Ansprechen kannst du jederzeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b04aa8-e3ca-474a-af0c-4aac0238c9b5', 'de', 'Welche Gewohnheiten sorgen dafür, dass du regelmäßig unter Leute kommst?', '["Im normalen Alltag mit Fremden reden", "Jeden Ort als Gelegenheit sehen, Kontakt zu üben", "Nur ansprechen, wenn du dich voll selbstbewusst fühlst"]'::jsonb, 'Regelmäßiger Kontakt senkt den Druck, und Begegnungen fallen dir leichter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cd29e03-754c-4a91-8b5a-132fe680704d', 'de', 'Wozu dient die Drei-Sekunden-Regel?', '["Dringlichkeit erzeugen", "Abfuhren vermeiden", "Opener perfektionieren", "Handeln, bevor sich Widerstand aufbaut"]'::jsonb, 'Schnelles Handeln verhindert, dass Zweifel aufkommen. Geh los, spätestens drei Sekunden nachdem du sie bemerkt hast.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71a2b057-c0c3-49ae-a552-62426201f6c9', 'de', 'Warum macht Warten das Ansprechen schwerer?', '["Die Angst vervielfacht sich", "Die Energie sinkt", "Das Interesse lässt nach", "Die Aufmerksamkeit wandert"]'::jsonb, 'Die Angst wächst, wenn dein Kopf Zeit hat, sich Szenarien auszumalen. Sei schnell.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8119be9-b1ef-4a0d-ab94-b3b7fdcf7ef2', 'de', 'Du siehst eine attraktive Frau in einer Bar und willst sie ansprechen. Was solltest du tun?', '["Anfangen, den perfekten Opener zu planen", "Erst über das Risiko einer Abfuhr nachdenken", "Innerhalb von drei Sekunden auf sie zugehen", "Stehen bleiben, bis du keine Angst mehr hast"]'::jsonb, 'Handle, bevor das Grübeln Widerstand und Zögern aufbaut.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50b60dd8-f15e-4fdb-bbb1-8651ce23d2c0', 'de', 'Warum ist es ihr unangenehm, wenn du ihr den Weg versperrst?', '["Es löst automatisch eine Bedrohungsreaktion aus", "Es wirkt unhöflich", "Es zeigt Dominanz"]'::jsonb, 'Der Körper reagiert auf eingeengten Raum, bevor der Verstand mitkommt. Lass ihr Platz.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eddec612-c258-4098-80cf-80aed2555258', 'de', 'Du sprichst sie an und merkst, dass sie nicht gut wegkommt. Was passt du am besten an?', '["Einen Schritt zurückgehen und Platz machen", "Schneller sprechen", "Ihr ein Kompliment machen"]'::jsonb, 'Wenn du anderen Platz lässt, bleibt ihr Nervensystem entspannt und offen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aea4811b-264d-435b-ab0a-4bcab3bc274a', 'de', 'Was sorgt dafür, dass sich die Ansprache angenehm anfühlt?', '["Sichtbar bleiben", "Ausgänge versperren", "Zu nah stehen", "Ihr Bewegungsfreiraum lassen"]'::jsonb, 'Sichtbarkeit und Platz halten ihr Nervensystem entspannt und offen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2e5b5d64-e126-4877-9449-ad662c2d047e', 'de', 'Was vermittelt ein entspannter Körper in Bewegung, bevor du etwas sagst?', '["Selbstbewusstsein, Wohlgefühl und eine harmlose Absicht", "Eine entschuldigende oder bedrohliche Ausstrahlung", "Das Bedürfnis nach sofortiger Bestätigung", "Desinteresse an der Umgebung"]'::jsonb, 'Fließende, offene Bewegungen schaffen unbewusst eine positive Grundlage.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e26bd7a-b3cd-4d6e-af6b-4122066f80b5', 'de', 'Du gehst mit ruckartigen, zögerlichen Schritten auf sie zu. Was tust du am besten?', '["Langsamer gehen, die Schultern lockern und dich sammeln, bevor du näher kommst", "Stehen bleiben und ihr stattdessen etwas zurufen", "So weitergehen, um Echtheit und Ehrlichkeit zu zeigen"]'::jsonb, 'Entspannte Bewegungen vermitteln Sicherheit, und das Gespräch fällt ihr leichter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
